import {SanityLogo} from '@sanity/logos'
import {Card, Heading, Text, usePrefersDark} from '@sanity/ui'
import {Fragment, type ReactNode} from 'react'
import {styled} from 'styled-components'
import {Box, Flex, VStack} from 'ui5'

const LINKS = [
  {
    url: 'https://snty.link/community',
    i18nKey: 'workspaces.community-title',
    title: 'Community',
  },
  {
    url: 'https://www.sanity.io/docs',
    i18nKey: 'workspaces.docs-title',
    title: 'Docs',
  },
  {
    url: 'https://www.sanity.io/legal/privacy',
    i18nKey: 'workspaces.privacy-title',
    title: 'Privacy',
  },
  {
    url: 'https://www.sanity.io',
    i18nKey: 'workspaces.sanity-io-title',
    title: 'sanity.io',
  },
]

const StyledText = styled(Text)`
  a {
    color: inherit;
  }
`

interface LayoutProps {
  header?: ReactNode
  children: ReactNode
  footer?: ReactNode
}

export function Layout(props: LayoutProps) {
  const {children, footer, header} = props
  const prefersDark = usePrefersDark()

  return (
    <VStack gap={6}>
      <Card border radius={3} overflow="auto">
        <VStack>
          {typeof header === 'object' && <Box>{header}</Box>}
          {typeof header === 'string' && (
            <Box paddingY={4}>
              <Heading align="center" size={1}>
                {header}
              </Heading>
            </Box>
          )}

          <Box paddingX={1}>
            <Card borderTop={Boolean(header)} borderBottom={Boolean(footer)}>
              {children}
            </Card>
          </Box>

          {footer && <Box>{footer}</Box>}
        </VStack>
      </Card>

      <Flex
        flexDirection="column"
        gap={4}
        justifyContent="center"
        alignItems="center"
        paddingBottom={4}
      >
        <Text size={3}>
          <SanityLogo dark={prefersDark} />
        </Text>

        <Flex alignItems="center" gap={2}>
          {LINKS.map((link, index) => (
            <Fragment key={link.title}>
              <StyledText muted size={1}>
                <a href={link.url} target="_blank" rel="noopener noreferrer">
                  {link.title}
                </a>
              </StyledText>

              {index < LINKS.length - 1 && (
                <Text size={1} muted>
                  •
                </Text>
              )}
            </Fragment>
          ))}
        </Flex>
      </Flex>
    </VStack>
  )
}
