import {type SanityClient} from '@sanity/client'
import {
  catchError,
  map,
  type Observable,
  of,
  retry,
  shareReplay,
  startWith,
  switchMap,
  timer,
} from 'rxjs'
import {mergeMapArray} from 'rxjs-mergemap-array'

import {type DocumentPreviewStore} from '../../preview/documentPreviewStore'
import {memoize} from '../../store/document/utils/createMemoizer'
import {createMemoKey, getClientCredentialSegments} from '../../store/document/utils/memoKey'
import {getPublishedId} from '../../util/draftUtils'
import {type CompanionDoc} from '../types'

export interface CanvasCompanionDocsStore {
  getCompanionDocs: (documentId: string) => Observable<CompanionDocs>
}
export interface CompanionDocs {
  data: CompanionDoc[]
  error: null | string
  loading: boolean
}
/**
 * What `getCompanionDocs` emits first, while the companion docs are being looked up.
 * @internal
 */
export const INITIAL_COMPANION_DOCS: CompanionDocs = {
  data: [],
  error: null,
  loading: true,
}

const getCompanionDocs = memoize(
  (
    publishedId: string,
    client: SanityClient,
    previewStore: DocumentPreviewStore,
  ): Observable<CompanionDocs> => {
    const allVersionIds$ = previewStore
      .unstable_observeDocumentIdSet(`sanity::versionOf($publishedId)`, {publishedId})
      .pipe(map((result) => result.documentIds))

    const companionDocsIdsListener$ = allVersionIds$.pipe(
      switchMap((versionIds) =>
        previewStore.unstable_observeDocumentIdSet(
          `_type == "sanity.canvas.link" && studioDocumentId in $ids`,
          {ids: versionIds},
        ),
      ),
    )

    const getCompanionDoc$ = (id: string) =>
      client.observable
        .fetch<CompanionDoc | null>(
          `*[_id == $id][0]{ _id, canvasDocumentId, studioDocumentId, isStudioDocumentEditable}`,
          {id},
          {tag: 'canvas.companion-docs'},
        )
        .pipe(
          map((response) => {
            if (!response?._id) {
              // In some race scenarios we can get the response in the listener before the document is available to be fetched.
              // This will only retry "not ready" errors, other errors will be propagated immediately
              throw new Error('Companion doc not ready')
            }
            return response
          }),
          retry({
            count: 2,
            delay: (error) => {
              if (error instanceof Error && error.message === 'Companion doc not ready') {
                return timer(1000)
              }

              throw error
            },
          }),
        )

    return companionDocsIdsListener$.pipe(
      map((value) => value.documentIds),
      mergeMapArray(getCompanionDoc$),
      map((value) => ({error: null, data: value, loading: false})),
      catchError((error) => of({error, data: [], loading: false})),
      startWith(INITIAL_COMPANION_DOCS),
      // refCount so the listener tears down when the last subscriber leaves.
      // Combined with the credential in the memo key below, a cross-tab
      // re-login's stale-token entry stops listening once the form remounts
      // onto the new client — a plain `shareReplay(1)` would keep the
      // stale-token listener connected forever and it would 401.
      shareReplay({bufferSize: 1, refCount: true}),
    )
  },
  // Keyed by the credential: this captures `client` and fetches/listens through
  // it, so a cross-tab re-login (new token) gets a fresh entry rather than
  // replaying the stale-token client. See getClientCredentialSegments.
  (publishedId, client) => createMemoKey([publishedId, ...getClientCredentialSegments(client)]),
)

/**
 * This store is used to get the companion docs for a given document bundle.
 * It uses the published id of the document and it sets up a listener `companionDocsIdsListener$` for document with type `sanity.canvas.link`
 * that have a `studioDocumentId` in the published, draft or version path of the document.
 *
 * The mentioned listener doesn't get the full document, it gets only the ids, so the subsequent request `getCompanionDoc$` is the one that handles
 * fetching the data for that companion doc obtained from the listener.
 *
 * The value is memoized based on the publishedId and the client config, ensuring that using the same publishedId and client config will return the same observable and won't start multiple listeners.
 */
export function createCanvasCompanionDocsStore({
  client,
  previewStore,
}: {
  client: SanityClient
  previewStore: DocumentPreviewStore
}): CanvasCompanionDocsStore {
  return {
    getCompanionDocs: (documentId: string) =>
      getCompanionDocs(getPublishedId(documentId), client, previewStore),
  }
}
